from .base_wrapper import BaseWrapper


class TestPcWrapper(BaseWrapper):
    """
    All redirections for host are contained inside this wrapper's properties
    """
    @property
    def addr(self):
        return self.tl_config.test_pc.default_ssh_connection_details.addr

    @property
    def username(self):
        return self.tl_config.test_pc.default_ssh_connection_details.username

    @property
    def password(self):
        return self.tl_config.test_pc.default_ssh_connection_details.password


class MmeIpWrapper(BaseWrapper):
    @property
    def addr(self):
        return self.tl_config.core.mme_ip


class _HostWrapper(BaseWrapper):
    def __getitem__(self, key):
        hosts = {1: TestPcWrapper(self.tl_config),
                 2: MmeIpWrapper(self.tl_config)}
        try:
            return hosts[key]
        except KeyError:
            raise IndexError
